import SwiftUI

// The cold-start splash: the web cover's walking Mulassa («sense frase»), layer by layer from the web's own art and keyframes
// (SplashArt.swift, generated by tools/app/splash.mjs). The launch screen shows her rest pose on the same brown at the same
// place; she eases from it into the walk, the cover's tile pattern fades in, and after one stride cycle the overlay fades out
// over the launcher (the catalogue and its art are read before the first frame). Reduce Motion keeps the rest pose.
struct SplashTrack { let dur: Double; let delay: Double; let ease: Int; let keys: [[CGFloat]] }
struct SplashNode { let parent: Int; let asset: String?; let origin: CGPoint; let opacity: CGFloat; let clip: Int; let clipBox: CGRect?; let track: SplashTrack? }

enum Splash {
    static var shown = false // once per process: not on a scene's reconnection or a return from a game
    static let hold = 0.96, fade = 0.25, blendIn = 0.2, tileIn = 0.3

    // The CSS timing functions the keyframes use: linear, ease-in-out, ease-out, ease (per segment, as CSS applies them).
    static func eased(_ x: CGFloat, _ ease: Int) -> CGFloat {
        let c: (CGFloat, CGFloat, CGFloat, CGFloat)
        switch ease { case 1: c = (0.42, 0, 0.58, 1); case 2: c = (0, 0, 0.58, 1); case 3: c = (0.25, 0.1, 0.25, 1); default: return x }
        let b = { (t: CGFloat, p1: CGFloat, p2: CGFloat) in 3 * (1 - t) * (1 - t) * t * p1 + 3 * (1 - t) * t * t * p2 + t * t * t }
        var lo: CGFloat = 0, hi: CGFloat = 1
        for _ in 0..<24 { let m = (lo + hi) / 2; if b(m, c.0, c.2) < x { lo = m } else { hi = m } }
        return b((lo + hi) / 2, c.1, c.3)
    }

    // [tx, ty, rotation°, sx, sy, opacity] of a node `t` seconds into the walk, `w` of the way from the rest pose.
    static func values(_ n: SplashNode, _ t: Double, _ w: CGFloat) -> [CGFloat] {
        let rest: [CGFloat] = [0, 0, 0, 1, 1, n.opacity]
        guard let tr = n.track, w > 0 else { return rest }
        var p = CGFloat(((t - tr.delay) / tr.dur).truncatingRemainder(dividingBy: 1)); if p < 0 { p += 1 }
        let i = tr.keys.lastIndex { $0[0] <= p } ?? 0, a = tr.keys[i], b = tr.keys[min(i + 1, tr.keys.count - 1)]
        let f = b[0] > a[0] ? eased((p - a[0]) / (b[0] - a[0]), tr.ease) : 0
        return (1...6).map { k in let v = a[k] + (b[k] - a[k]) * f; return rest[k - 1] + (v - rest[k - 1]) * w }
    }
}

// Seconds since the splash's first frame, ticked by the host's display link (a TimelineView never ticked in its window).
final class SplashClock: ObservableObject { @Published var t = 0.0 }

struct SplashView: View {
    let still: Bool
    @ObservedObject var clock: SplashClock

    var body: some View {
        Canvas { ctx, size in draw(ctx, size, clock.t) }
            .background(Color(rgb: SplashArt.background))
            .ignoresSafeArea()
    }

    private func draw(_ ctx: GraphicsContext, _ size: CGSize, _ t: Double) {
        // the cover's pattern, one tile per 9 s ↘ (still with Reduce Motion), fading in: the launch screen has none
        let tile = ctx.resolve(Image("splash-tile")), s = SplashArt.tile
        let drift = still ? 0 : CGFloat((t / SplashArt.tileDrift).truncatingRemainder(dividingBy: 1)) * s
        var bg = ctx
        bg.opacity = min(1, t / Splash.tileIn)
        for y in stride(from: drift - s, to: size.height, by: s) {
            for x in stride(from: drift - s, to: size.width, by: s) { bg.draw(tile, in: CGRect(x: x, y: y, width: s, height: s)) }
        }
        // the figure: units → points, its centre on the screen's (the launch screen's image is centred there too)
        let k = SplashArt.size, fig = SplashArt.figure
        let place = CGAffineTransform(scaleX: k, y: k)
            .concatenating(CGAffineTransform(translationX: size.width / 2 - fig.width / 2 * k, y: size.height / 2 - fig.height / 2 * k))
        let w = still ? 0 : CGFloat(min(1, t / Splash.blendIn)), wSmooth = w * w * (3 - 2 * w)
        var m = [CGAffineTransform](), o = [CGFloat]()
        for n in SplashArt.nodes {
            let v = Splash.values(n, t, wSmooth)
            let local = CGAffineTransform(translationX: -n.origin.x, y: -n.origin.y)
                .concatenating(CGAffineTransform(scaleX: v[3], y: v[4]))
                .concatenating(CGAffineTransform(rotationAngle: v[2] * .pi / 180))
                .concatenating(CGAffineTransform(translationX: n.origin.x + v[0], y: n.origin.y + v[1]))
            m.append(n.parent < 0 ? local : local.concatenating(m[n.parent]))
            o.append(v[5] * (n.parent < 0 ? 1 : o[n.parent]))
            guard let asset = n.asset, o.last! > 0 else { continue }
            var c = ctx
            if n.clip >= 0, let box = SplashArt.nodes[n.clip].clipBox { // a still box (the generator checks)
                c.transform = place
                c.clip(to: Path(m[n.clip].isIdentity ? box : box.applying(m[n.clip])))
            }
            c.opacity = o.last!
            c.transform = m.last!.concatenating(place)
            c.draw(Image(asset), in: SplashArt.view)
        }
    }
}

private extension Color {
    init(rgb: Int) { self.init(red: Double(rgb >> 16 & 255) / 255, green: Double(rgb >> 8 & 255) / 255, blue: Double(rgb & 255) / 255) }
}
